{
  "claude": {
    "description": "Claude Code に許すこと",
    "type": "object",
    "additionalProperties": false,
    "required": [
      "allow"
    ],
    "properties": {
      "allow": {
        "description": "許すツール",
        "x-prompt": {
          "read": {
            "means": "--allowedTools に渡すツールの名前である。${entry} は brainstorming の実行ファイル（リポジトリの根から）に置き換わる。"
          },
          "write": [
            {
              "id": "entry-kept",
              "rule": "Bash(${entry}:*) を必ず入れる。",
              "why": "無いと、AI がボードを update で直せない。",
              "test": "値の中に Bash(${entry}:*) があるかを見る。"
            },
            {
              "id": "paths-from-root",
              "rule": "Bash で許すコマンドは、リポジトリの根からの経路で書く。",
              "why": "AI はリポジトリの根で動く。",
              "test": "経路のファイルがあるかを見る。"
            }
          ]
        },
        "type": "array",
        "minItems": 1,
        "uniqueItems": true,
        "contains": {
          "const": "Bash(${entry}:*)"
        },
        "items": {
          "type": "string",
          "minLength": 1,
          "pattern": "^(?!.*(dangerously|bypass)).*$"
        }
      }
    }
  },
  "codex": {
    "description": "Codex に許すこと",
    "type": "object",
    "additionalProperties": false,
    "required": [
      "sandbox"
    ],
    "properties": {
      "sandbox": {
        "description": "sandbox",
        "x-prompt": {
          "read": {
            "means": "Codex の --sandbox に渡す値である（続きでは -c sandbox_mode に渡す）。"
          },
          "write": [
            {
              "id": "two",
              "rule": "read-only か workspace-write を書く。",
              "why": "ボードを直すには workspace-write が要る。",
              "test": "値を見る。"
            }
          ]
        },
        "enum": [
          "read-only",
          "workspace-write"
        ]
      }
    }
  },
  "kiro": {
    "description": "Kiro に許すこと",
    "type": "object",
    "additionalProperties": false,
    "required": [
      "trust"
    ],
    "properties": {
      "trust": {
        "description": "信頼するツール",
        "x-prompt": {
          "read": {
            "means": "--trust-tools に , でつないで渡すツールの名前である。"
          },
          "write": [
            {
              "id": "verified",
              "rule": "fs_read だけを書く。",
              "why": "help の出力で確かめた読むツールは fs_read だけである。",
              "test": "値を見る。"
            }
          ]
        },
        "type": "array",
        "uniqueItems": true,
        "items": {
          "enum": [
            "fs_read"
          ]
        }
      }
    }
  },
  "guide": {
    "description": "使い方の文",
    "type": "array",
    "items": {
      "type": "string",
      "minLength": 1
    }
  }
}
